fn hex_to_bytes(s: &str) -> Vec<u8> {
    s.as_bytes()
        .chunks_exact(2)
        .map(|pair| {
            let high = match pair[0] {
                b'0'..=b'9' => pair[0] - b'0',
                b'a'..=b'f' => pair[0] - b'a' + 10,
                b'A'..=b'F' => pair[0] - b'A' + 10,
                _ => 0,
            };
            let low = match pair[1] {
                b'0'..=b'9' => pair[1] - b'0',
                b'a'..=b'f' => pair[1] - b'a' + 10,
                b'A'..=b'F' => pair[1] - b'A' + 10,
                _ => 0,
            };
            (high << 4) | low
        })
        .collect()
}

fn rc4_ksa(key: &[u8]) -> Vec<u8> {
    let mut s = (0..=255).collect::<Vec<_>>();
    let mut j: u8 = 0;
    for i in 0..=255 {
        j = j + s[i] + key[i % key.len()];
        s.swap(i as usize, j as usize);
    }
    s
}

fn rc4_prga(s: &mut [u8], data: &[u8]) -> Vec<u8> {
    let mut output = Vec::new();
    let mut i: u8 = 0;
    let mut j: u8 = 0;
    for &byte in data {
        i = i + 1;
        j = j + s[i as usize];
        s.swap(i as usize, j as usize);
        output.push(byte ^ s[(s[i as usize] + s[j as usize]) as usize]);
    }
    output
}

fn main() {
    let key = b"12345678abcdefghijklmnopqrspxyz";
    let encrypted = hex_to_bytes("9ee7305fa701a653591b0a20f173d10eab09840e8d2b");

    let ciphertext: Vec<u8> = rc4_prga(&mut rc4_ksa(key), &encrypted)
        .iter()
        .map(|&b| b ^ 0x22)
        .collect();
    println!("{}", String::from_utf8_lossy(&ciphertext));
}
