`HighTemplar::HighTemplar`

将输入`v18`存两次到入`&v23+16`和`&v23+48`，将`"327a6c4304ad5938eaf0efb6cc3e53dc"`存入到`&v23+80`

```C++
unsigned __int64 __fastcall HighTemplar::HighTemplar(DarkTemplar *a1, __int64 a2)
{
  char v3; // [rsp+17h] [rbp-19h] BYREF
  unsigned __int64 v4; // [rsp+18h] [rbp-18h]

  v4 = __readfsqword(0x28u);
  DarkTemplar::DarkTemplar(a1);
  *a1 = &off_401EA0;
  *(a1 + 3) = 0;
  std::string::basic_string(a1 + 16, a2);
  std::string::basic_string(a1 + 48, a2);
  std::allocator<char>::allocator(&v3);
  std::string::basic_string(a1 + 80, "327a6c4304ad5938eaf0efb6cc3e53dc", &v3);
  std::allocator<char>::~allocator(&v3);
  return __readfsqword(0x28u) ^ v4;
}
