`HighTemplar::calculate`

判断`&v23+16`的长度是否是32，然后两次循环修改`&v23+16`到`&v23+16+32`的内容

```C++
bool __fastcall HighTemplar::calculate(HighTemplar *this)
{
  __int64 v1; // rax
  _BYTE *v2; // rbx
  bool result; // al
  _BYTE *v4; // rbx
  int i; // [rsp+18h] [rbp-18h]
  int j; // [rsp+1Ch] [rbp-14h]

  if ( std::string::length(this + 16) != 32 )
  {
    v1 = std::operator<<<std::char_traits<char>>(&std::cout, "Too short or too long");
    std::ostream::operator<<(v1, &std::endl<char,std::char_traits<char>>);
    exit(-1);
  }
  for ( i = 0; i <= std::string::length(this + 16); ++i )
  {
    v2 = std::string::operator[](this + 16, i);
    *v2 = (*std::string::operator[](this + 16, i) ^ 0x50) + 23;
  }
  for ( j = 0; ; ++j )
  {
    result = j <= std::string::length(this + 16);
    if ( !result )
      break;
    v4 = std::string::operator[](this + 16, j);
    *v4 = (*std::string::operator[](this + 16, j) ^ 0x13) + 11;
  }
  return result;
}
